/**
 * Opening gatefold: two panels of debossed-lotus suede (one image spanning
 * both, public/images/texture/lotus-panel.webp, generated by scripts/generate-assets.mjs)
 * and a diamond lace seal with the couple's monogram, pinned to the left
 * panel so it swings away with it. Original SVG.
 */

const n = (v) => Math.round(v * 100) / 100;

/** Shared gradients used by the seal. */
export function doorSymbol() {
  return `
  <linearGradient id="dv-gold" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="#E9D3A5"/><stop offset=".5" stop-color="#C9A45C"/><stop offset="1" stop-color="#9C7638"/>
  </linearGradient>
  <radialGradient id="ds-paper" cx="45%" cy="36%" r="72%">
    <stop offset="0" stop-color="#FFFCF5"/><stop offset=".65" stop-color="#F3EBDD"/><stop offset="1" stop-color="#E2D6C2"/>
  </radialGradient>`;
}

/** Points on a softened diamond (superellipse), from the top, clockwise. */
function lozenge(cx, cy, a, b, count, p = 1.2) {
  const pts = [];
  for (let i = 0; i < count; i++) {
    const t = (i / count) * Math.PI * 2;
    const s = Math.sin(t);
    const c = Math.cos(t);
    pts.push([cx + a * Math.sign(s) * Math.abs(s) ** (2 / p), cy - b * Math.sign(c) * Math.abs(c) ** (2 / p)]);
  }
  return pts;
}

/** Scalloped outline through the points (each lobe bulges outward). */
function scallops(pts, depth = 0.6) {
  let d = `M${n(pts[0][0])} ${n(pts[0][1])}`;
  for (let i = 1; i <= pts.length; i++) {
    const [x0, y0] = pts[i - 1];
    const [x1, y1] = pts[i % pts.length];
    const r = Math.hypot(x1 - x0, y1 - y0) * depth;
    d += `A${n(r)} ${n(r)} 0 0 1 ${n(x1)} ${n(y1)}`;
  }
  return `${d}Z`;
}

const polygon = (pts) => `M${pts.map(([x, y]) => `${n(x)} ${n(y)}`).join('L')}Z`;

/** Diamond lace seal with an embossed monogram. */
export function seal([a, b]) {
  const cx = 82;
  const cy = 94;
  const outer = scallops(lozenge(cx, cy, 72, 86, 36), 0.62);
  const lace = scallops(lozenge(cx, cy, 63, 76, 28), 0.7);
  const inner = polygon(lozenge(cx, cy, 52, 63, 64));
  // tiny lace eyelets between the outer and inner lines
  const eyelets = lozenge(cx, cy, 67.5, 81, 36)
    .map(([x, y]) => `<circle cx="${n(x)}" cy="${n(y)}" r="1.5"/>`)
    .join('');
  const mono = (dx, dy, fill, op) =>
    `<g fill="${fill}" fill-opacity="${op}" font-family="Cinzel, serif" font-size="38" font-weight="500" text-anchor="middle" transform="translate(${dx} ${dy})">
      <text x="${cx - 18}" y="${cy + 6}">${a}</text>
      <text x="${cx + 18}" y="${cy + 22}">${b}</text>
    </g>`;
  return `<svg class="doors__seal" viewBox="0 0 164 188" aria-hidden="true" focusable="false">
    <path d="${outer}" fill="url(#ds-paper)" stroke="#CDBFA6" stroke-width=".9"/>
    <path d="${lace}" fill="none" stroke="#B9A88A" stroke-width=".8" stroke-opacity=".9"/>
    <g fill="none" stroke="#B9A88A" stroke-width=".7">${eyelets}</g>
    <path d="${inner}" fill="#FBF6EC" stroke="url(#dv-gold)" stroke-width="1.3"/>
    <path d="${polygon(lozenge(cx, cy, 47, 57, 64))}" fill="none" stroke="#C9A45C" stroke-opacity=".55" stroke-width=".7" stroke-dasharray="1.5 2.5"/>
    <use href="#o-lotus" x="${cx - 9}" y="${cy - 50}" width="18" height="11"/>
    <use href="#o-lotus" x="${cx - 9}" y="${cy + 39}" width="18" height="11" transform="rotate(180 ${cx} ${cy + 44.5})"/>
    ${mono(0, 0.9, '#FFFFFF', 0.9)}
    ${mono(0, -0.7, '#5A4A35', 0.45)}
    ${mono(0, 0, '#9B8668', 1)}
  </svg>`;
}
